// Типы данных для профессий

export interface Profession {
  id: string;
  title: string;
  image: string; // Путь к изображению
  description: string; // Расширенное описание профессии (300-400 слов)
  suitableFor: string; // Кому подходит (200-250 слов)
  skills: {
    hard: string[];
    soft: string[];
  };
  salary: {
    min: number;
    max: number;
    description: string;
  };
  education: Array<{
    code: string;
    title: string;
    level: string; // СПО, Бакалавриат, Магистратура
  }>;
  careerPath: string;
  // Новые поля для SEO
  responsibilities?: string[]; // Обязанности и функции
  prosAndCons?: {
    pros: string[];
    cons: string[];
  }; // Плюсы и минусы профессии
  demand?: string; // Востребованность на рынке труда (150-200 слов)
  workPlaces?: string[]; // Где можно работать
  howToBecome?: string; // Как стать специалистом (200-300 слов)
  famousPeople?: string[]; // Известные представители профессии
  relatedProfessions?: string[]; // Смежные профессии
}

