// Функция для получения профессии по ID
export function getProfessionById(id: string): Profession | undefined {
  return professions.find(p => p.id === id);
}

// Функция для пагинации
export function getProfessionPage(page: number, perPage: number = 25): Profession[] {
  const start = (page - 1) * perPage;
  const end = start + perPage;
  return professions.slice(start, end);
}

// Общее количество страниц
export function getTotalPages(perPage: number = 25): number {
  return Math.ceil(professions.length / perPage);
}

// Общее количество профессий
export function getTotalProfessions(): number {
  return professions.length;
}
